/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.7 Confirm shipments
/// Determines whether a record in the <c>MetCarrierSealTable</c> table exists for a specified custom shipment Id.
/// </summary>
/// <param name="_shipmentId">
///  The custom shipment Id of the <c>MetCarrierSealTable</c> to find.
/// </param>
/// <returns>
/// true if the specified record exists; otherwise, false.
/// </returns>
public static boolean existShipmentId(METShipmentId _shipmentId)
{
    return _shipmentId && (select firstonly RecId from MetContainerTable
            where MetContainerTable.ShipmentId == _shipmentId).RecId != 0;
}

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip Find method
    /// </summary>
    /// <param name = "_shipmentId">SO finalisation shipment Id</param>
    /// <param name = "_containerTypeCode">Container type code</param>
    /// <param name = "_update">Select for update</param>
    /// <returns><c>METPicklistReference</c> record if found; otherwise, null.</returns>
    static MetContainerTable find(MetShipmentId         _shipmentId,
                                  WHSContainerTypeCode  _containerTypeCode,
                                  boolean               _update = false)
    {
        MetContainerTable containerTable;

        if (_shipmentId && _containerTypeCode)
        {
            if (_update)
            {
                containerTable.selectForUpdate(_update);
            }
            
            select firstonly containerTable
                       where containerTable.ShipmentId == _shipmentId
                          && containerTable.ContainerTypeCode == _containerTypeCode;

        }

        return containerTable;
    }

    /// <summary>
    /// update sales order number
    /// </summary>
    public void updateSalesOrderNum()
    {
        METOrderReference orderNum = this.findSalesOrderNumByContainerType();

        if(orderNum)
        {
            ttsbegin;
            this.selectForUpdate(true);
            this.OrderNum = orderNum;
            this.update();
            ttscommit;
        }
    }

private METOrderReference findSalesOrderNumByContainerType()
{
    METOrderReference ret;
    
    switch(WHSContainerType::find(this.ContainerTypeCode).METWHSContainerChargesMethod)
    {
        case METWHSContainerChargesMethod::SecurityCap:
            ret = this.findSalesOrderNumByChargesMethod(METChargesMethod::SecurityCap);
            break;
        case METWHSContainerChargesMethod::ShrinkWrap:
            ret = this.findSalesOrderNumByChargesMethod(METChargesMethod::Pallet);
            break;
    }
    
    return ret;
}

    private METOrderReference findSalesOrderNumByChargesMethod(METChargesMethod _chargesMethod)
    {
        METSalesOrderShipmentLoadLines salesOrderShipmentLoadLines;
        MarkupTrans markupTrans;
        SalesTable salesTable;

        select firstonly SalesId from salesTable
            order by salesTable.CreatedDateTime desc
            exists join salesOrderShipmentLoadLines
            where salesOrderShipmentLoadLines.ShipmentId == this.ShipmentId
               && salesOrderShipmentLoadLines.OrderNum == salesTable.SalesId
            exists join markupTrans
            where markupTrans.TransTableId == salesTable.TableId
               && markupTrans.TransRecId == salesTable.RecId
               && markupTrans.METChargesMethod == _chargesMethod;

        return salesTable.SalesId;
    }

    /// <summary>
    /// insert
    /// </summary>
    public void insert()
    {
        super();

        this.updateSalesOrderNum();
    }
